if (process.env.CAMPAIGN_BLOCKED === 'true') {
  runner = replaceOnce(
    runner,
    `  for (let i = jobs.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1));
    [jobs[i], jobs[j]] = [jobs[j], jobs[i]];
  }`,
    `  // Randomized blocks keep both variants of a case adjacent; their order
