const app = "/Users/romaingeffrault/Documents/projects/prive/craft-ts-imperative-render/apps/compiler-benchmark", root = "/Users/romaingeffrault/Documents/projects/prive/craft-ts-imperative-render";
const output = resolve(
  root,
